package top.monitorglobal.tv;
import android.content.Context;import android.graphics.*;import android.view.*;import android.widget.*;import org.json.*;import org.junit.*;import static org.junit.Assert.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;
/** Real Android layout/Skia checks for the approved solid broadcast cards. */
@RunWith(RobolectricTestRunner.class) @Config(sdk=35,qualifiers="w1280dp-h720dp-land-hdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class WeatherCardsDesignTest {
 private Context c;private int dp(int n){return Math.round(n*c.getResources().getDisplayMetrics().density);}
 @Before public void setup(){c=RuntimeEnvironment.getApplication();}
 private WeatherForecast.Summary weather(){return new WeatherForecast.Summary("18°C · sensação 19°C","Nublado","Vento 9 km/h · rajadas 19 km/h","Umidade 92%","Modelo horário · ref. 19:00 BRT · gerado 19:17 BRT",System.currentTimeMillis()+600000,false,"18°C","19°C","92%","9 km/h","19 km/h","Cloudy");}
 private RainForecast.Summary rain(boolean knownEnd)throws Exception{long now=System.currentTimeMillis(),start=now/60000*60000;JSONArray points=new JSONArray();for(int i=0;i<90;i++){boolean wet=i>=15&&(!knownEnd||i<40);points.put(new JSONObject().put("start",start+i*60000).put("end",start+(i+1)*60000).put("rate",wet?6:0).put("type",wet?"rain":"no_precipitation"));}return RainForecast.summarize(new JSONObject().put("version","tv-rain-v1").put("area","liberdade").put("ok",true).put("at",now).put("expiresAt",now+600000).put("loc",new JSONObject().put("lat",RainForecast.LATITUDE).put("lng",RainForecast.LONGITUDE)).put("forecast",points),now);}
 private String texts(View view){if(view instanceof TextView)return ((TextView)view).getText().toString();StringBuilder b=new StringBuilder();if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++)b.append(texts(((ViewGroup)view).getChildAt(i))).append(" ");return b.toString();}
 private void layout(WeatherCardView card){int width=Math.min(dp(420),1280*46/100),height=720-2*dp(28);card.measure(View.MeasureSpec.makeMeasureSpec(width,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(height,View.MeasureSpec.AT_MOST));card.layout(0,0,card.getMeasuredWidth(),card.getMeasuredHeight());assertTrue("card fits a 720p TV with margins",card.getHeight()<height);assertTrue(card.getHeight()>dp(120));checkText(card);}
 private void checkText(View view){if(view instanceof TextView){TextView t=(TextView)view;assertNotNull(t.getLayout());assertTrue("text height fits its view: "+t.getText(),t.getLayout().getHeight()<=t.getHeight());assertTrue("full text fits the allocated line count: "+t.getText(),t.getLayout().getLineEnd(t.getLayout().getLineCount()-1)>=t.getText().length());assertTrue("text remains inside card: "+t.getText(),t.getRight()<=((View)t.getParent()).getWidth());}if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++)checkText(((ViewGroup)view).getChildAt(i));}
 private void export(WeatherCardView card,String name)throws Exception{Bitmap b=Bitmap.createBitmap(card.getWidth(),card.getHeight(),Bitmap.Config.ARGB_8888);try{card.draw(new Canvas(b));View header=card.getChildAt(0),body=card.getChildAt(1),footer=card.getChildAt(card.getChildCount()-1);assertEquals(WeatherCardView.CYAN,b.getPixel(2,header.getTop()+2));assertEquals(WeatherCardView.BODY,b.getPixel(2,body.getTop()+2));assertEquals(WeatherCardView.FOOT,b.getPixel(2,footer.getTop()+2));try(java.io.FileOutputStream out=new java.io.FileOutputStream(new java.io.File(System.getProperty("java.io.tmpdir"),"monitor-tv-weather-card-"+name+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,out);}}finally{b.recycle();}}
 @Test public void hourlyCardHasLargeTemperatureMetricsAndUnavailableRainWithoutInventingZero()throws Exception{WeatherCardView card=new WeatherCardView(c,null,weather(),false,false);String s=texts(card);assertTrue(s.contains("18°C"));assertTrue(s.contains("Sensação 19°C"));assertTrue(s.contains("92%"));assertTrue(s.contains("9 km/h"));assertTrue(s.contains("19 km/h"));assertTrue(s.contains("Chuva por minuto: indisponível"));assertTrue(s.contains("Modelo horário"));assertFalse(s.contains("0,0 mm"));layout(card);export(card,"hourly");}
 @Test public void hourlyCardRemainsTemperatureFocusedWhenRainIsAlsoForecast()throws Exception{RainForecast.Summary rain=rain(true);assertNotNull(rain);WeatherCardView card=new WeatherCardView(c,rain,weather(),false,false);String s=texts(card);assertTrue(s.contains("TEMPO · LIBERDADE, SP"));assertTrue(s.contains("18°C"));assertTrue(s.contains("Sensação 19°C"));assertTrue(s.contains("prevista em ~15 min"));assertTrue(s.contains("2,5 mm"));assertTrue(s.contains("Modelo horário"));layout(card);export(card,"hourly-rain");}
 @Test public void unknownEndStaysIndefiniteAndNoCurrentHourlyWeatherIsFabricated()throws Exception{WeatherCardView card=new WeatherCardView(c,rain(false),null,false,false);String s=texts(card);assertTrue(s.contains("Duração ainda indefinida"));assertTrue(s.contains("Término sem estimativa disponível"));assertFalse(s.contains("18°C"));assertFalse(s.contains("~0 min"));layout(card);export(card,"unknown-end");}
 @Test public void oldLocalFixturesStayExplicitAndWeatherConditionsUseHonestIcons()throws Exception{WeatherForecast.Summary fixture=new WeatherForecast.Summary("22°C · sensação 23°C","Chuva · exemplo fictício","Vento 12 km/h · rajadas 19 km/h","Umidade 81%","SIMULAÇÃO",System.currentTimeMillis()+600000);WeatherCardView card=new WeatherCardView(c,null,fixture,true,false);assertTrue(texts(card).contains("TESTE FICTÍCIO"));assertTrue(texts(card).contains("22°C · sensação 23°C"));assertTrue(texts(card).contains("DEMONSTRAÇÃO LOCAL"));assertEquals(WeatherCardView.Icon.UNKNOWN,WeatherCardView.conditionIcon("Unrecognized"));assertEquals(WeatherCardView.Icon.SNOW,WeatherCardView.conditionIcon("Snow"));assertEquals(WeatherCardView.Icon.RAIN,WeatherCardView.conditionIcon("Thunderstorms"));layout(card);}
 @Test public void fullRainAndHourlyPreviewFits720pWithoutHidingItsFictionalLabels()throws Exception{WeatherCardView card=new WeatherCardView(c,rain(true),weather(),true,true);assertTrue(texts(card).contains("PRÉVIA VISUAL FICTÍCIA"));assertTrue(texts(card).contains("DEMONSTRAÇÃO LOCAL"));layout(card);export(card,"preview");}
}
